  const [pdfExportState, setPdfExportState] = useState<"idle" | "success" | "error">("idle");
  const [journalItems, setJournalItems] = useState<Array<any>>([]);
  const [status, setStatus] = useState<"all" | "succeeded" | "disabled" | "failed">("all");
  const [trigger, setTrigger] = useState<"all" | "heartbeat" | "manual">("all");
  const [search, setSearch] = useState("");
  const [errorCode, setErrorCode] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [calendarRange, setCalendarRange] = useState<DateRange | undefined>();
  const [slaRecipientEmail, setSlaRecipientEmail] = useState("");
