  const [sort, setSort] = useState<"evaluated_desc" | "evaluated_asc" | "duration_desc" | "duration_asc">("evaluated_desc");
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem("admin-metrics-theme") === "dark");
  const since = useMemo(() => new Date(Date.now() - days * 86400000), [days]);
  const metricsSince = useMemo(() => from ? new Date(`${from}T00:00:00.000Z`) : since, [from, since]);
  const metricsUntil = useMemo(() => to ? new Date(`${to}T23:59:59.999Z`) : undefined, [to]);
  const runInput = useMemo(() => ({ ...(status !== "all" ? { status } : {}), ...(trigger !== "all" ? { trigger } : {}), ...(search.trim() ? { search: search.trim() } : {}), ...(errorCode.trim() ? { errorCode: errorCode.trim() } : {}), ...(from ? { from } : {}), ...(to ? { to } : {}), sort, page, pageSize }), [status, trigger, search, errorCode, from, to, page, pageSize]);
  const metrics = trpc.admin.metrics.useQuery({ since: metricsSince, ...(metricsUntil ? { until: metricsUntil } : {}) }, { staleTime: 30_000 });
  const runs = trpc.admin.slaEvaluationRuns.useQuery(runInput, { staleTime: 30_000 });
  useEffect(() => {
    if (!runs.data) return;
    setJournalItems((previous) => { const next = page === 1 ? runs.data.items : [...previous, ...runs.data.items.filter((item) => !previous.some((existing) => existing.id === item.id))]; return next.length === previous.length && next.every((item, index) => item.id === previous[index]?.id) ? previous : next; });
  }, [runs.data, page]);
  useEffect(() => {
    if (journalMode !== "infinite" || !loadMoreRef.current || !runs.data || page >= runs.data.totalPages) return;
    const observer = new IntersectionObserver(([entry]) => { if (entry.isIntersecting && !runs.isFetching) setPage((value) => value + 1); }, { rootMargin: "240px" });
    observer.observe(loadMoreRef.current);
    return () => observer.disconnect();
  }, [journalMode, page, runs.data, runs.isFetching]);
  const settings = trpc.admin.slaSettings.useQuery();
  const utils = trpc.useUtils();
  const update = trpc.admin.updateSlaSettings.useMutation({ onSuccess: () => utils.admin.slaSettings.invalidate() });
