  const updateAllowlist = trpc.admin.updateSlaEmailAllowlist.useMutation({ onSuccess: () => utils.admin.slaEmailAllowlist.invalidate() });
  const removeAllowlist = trpc.admin.removeSlaEmailAllowlist.useMutation({ onSuccess: () => utils.admin.slaEmailAllowlist.invalidate() });
  const current = settings.data;
