  const form = draft ?? (current ? { enabled: current.enabled, preparationHours: current.preparationHours, deliveryHours: current.deliveryHours, alertCooldownMinutes: current.alertCooldownMinutes } : { enabled: true, preparationHours: 48, deliveryHours: 24, alertCooldownMinutes: 60 });
  const setField = <K extends keyof typeof form>(key: K, value: (typeof form)[K]) => setDraft({ ...form, [key]: value });
